 if(settings.sections.includes('finance'))sectionHtml.push('<section class="dash-panel"><div class="dash-section-head"><div><h3>আর্থিক সারাংশ</h3><p>আজকের অনুমোদিত লেনদেন</p></div></div><div id="dashFinanceNotice" class="dash-empty">হিসাবের তথ্য লোড হচ্ছে…</div><div class="dash-bars"><div><span>আয়</span><div class="dash-bar-track"><i id="dashIncomeBar"></i></div></div><div><span>ব্যয়</span><div class="dash-bar-track"><i id="dashExpenseBar"></i></div></div></div></section>');
 if(settings.sections.includes('upcoming'))sectionHtml.push('<section class="dash-panel"><div class="dash-section-head"><div><h3>আসন্ন অনুষ্ঠান</h3><p>ক্যালেন্ডারে সংরক্ষিত ভবিষ্যৎ আয়োজন</p></div><a href="#admin=m04">সব দেখুন →</a></div><div id="dashUpcoming" class="dash-list"><p class="dash-empty">লোড হচ্ছে…</p></div></section>');
 if(settings.sections.includes('recent'))sectionHtml.push('<section class="dash-panel"><div class="dash-section-head"><div><h3>সাম্প্রতিক কার্যক্রম</h3><p>সর্বশেষ হালনাগাদ করা রেকর্ড</p></div><a href="#admin=m03">কার্যক্রম লগ →</a></div><div id="dashRecent" class="dash-list"><p class="dash-empty">লোড হচ্ছে…</p></div></section>');
 w.innerHTML='<div class="dash-head"><div><p class="dash-eyebrow">ADMIN CONTROL CENTER</p><h2>প্রশাসনিক ড্যাশবোর্ড</h2><p class="muted">স্বাগতম, '+escapeHtml(profile.full_name||user.email)+' · '+escapeHtml(roleNames[profile.role]||profile.role)+'</p><p class="dash-date">'+escapeHtml(dateLabel)+'</p></div><div class="dash-head-actions"><button id="dashboardRefresh" type="button">↻ রিফ্রেশ</button>'+(canSeeAccounts?'<a class="dash-link-button" href="./accounts.html">হিসাব ব্যবস্থাপনা ↗</a>':'')+'</div></div>'+
 (profile.role==='super_admin'?'<div class="dash-head-actions"><button id="dashboardSettingsToggle" type="button">⚙ ড্যাশবোর্ড সাজান</button></div>'+dashboardSettingsMarkup(settings):'')+
 '<div class="dash-metrics">'+metricCards+'</div>'+
 (sectionHtml.length?'<div class="dash-columns">'+sectionHtml.map((x,i)=>'<div class="dash-column-item">'+x+'</div>').join('')+'</div>':'<p class="dash-empty">ড্যাশবোর্ডে এখনো কোনো বিভাগ নির্বাচন করা হয়নি। সুপার অ্যাডমিন সেটিংস থেকে বিভাগ যোগ করতে পারবেন।</p>')+
 '<div class="dash-footer-note">ড্যাশবোর্ডের পরিসংখ্যান Supabase ডেটাবেস ও আপনার অ্যাকাউন্টের Row Level Security অনুমতি অনুযায়ী দেখানো হয়। অনুমতি না থাকলে সংশ্লিষ্ট তথ্য দেখানো হবে না।</div>';
